const prepared = $('Prepare Manual Paid Durable Intake').first()?.json?.request;
const executionId = String($execution.id);
if (!/^[0-9]{1,30}$/.test(executionId) || prepared?.executionId !== executionId ||
    prepared?.scope !== 'MANUAL_SHOPIFY_PAID' || !['claim','admit'].includes(prepared.operation) ||
    !Array.isArray(prepared.candidates)) throw new Error('MANUAL_PAID_CLAIM_CONTEXT_INVALID');
const input = $input.first()?.json || {};
const error = input.error;
const codes = [error?.httpCode,error?.statusCode,error?.status,error?.response?.statusCode,input.statusCode]
  .filter(value => value !== undefined && value !== null && value !== '').map(String);
const httpStatus = codes.length && codes.every(value => value === codes[0]) && /^[45][0-9]{2}$/.test(codes[0]) ? codes[0] : 'unknown';
const ids = [...new Set(prepared.candidates.map(row => String(row?.shopifyOrderId || '')).filter(id => /^[0-9]{1,30}$/.test(id)))];
const context = 'executionId=' + executionId + '; operation=' + prepared.operation + '; httpStatus=' + httpStatus
  + '; candidateOrderIds=' + (ids.slice(0,5).join(',') || 'none') + '; candidateCount=' + prepared.candidates.length
  + '; selection=unknown';
throw new Error('MANUAL_PAID_CLAIM_UNCONFIRMED; ' + context
  + '; Übernahme nicht bestätigt. Dauerhaften Claim-Beleg zu dieser Ausführung prüfen. Kandidaten sind kein Nachweis des ausgewählten Auftrags. Fehlender Beleg bedeutet ungeklärt. Kein automatischer Neuversuch.');
